const sha256Pattern = /^[a-f0-9]{64}$/;
const allowedKinds = new Set<GameAssetKind>(["SWF", "HTML5_BUNDLE", "IMAGE", "AUDIO"]);
const allowedDeliveries = new Set<GameAssetDelivery>(["APP_STATIC", "R2_CUSTOM_DOMAIN"]);
